command:
/**
 * SVA example: Energy Strands Toggle
 * Crackling strands of energy swirl around each selected token (a base layer under the token and
 * an overlay above it). Run again to fade them out.
 *
 * Usage: select tokens, run. Change COLOR below.
 * Requires: Sargas Visual Automation + JB2A (Patreon). No Sequencer needed.
 */
const SVA = game.modules.get("sargas-visual-automation")?.api;
if (!SVA?.ready) return ui.notifications.error("Sargas Visual Automation is not ready.");

// blue, grey, blueorange, dark_green, dark_red, dark_purple, dark_purple02, orange, pinkyellow, purple
const COLOR = "dark_red";
const SCALE = 1.6;
const FADE_MS = 1000;

const tokens = canvas.tokens.controlled;
if (!tokens.length) return ui.notifications.warn("Select at least one token.");
const sceneId = canvas.scene.id;

for (const tok of tokens) {
  const name = `sva-energy-strands:${tok.id}`;
  if (SVA.effects.list({ sceneId, name }).length) {
    await SVA.effects.end({ name, sceneId });
    continue;
  }
  const seq = SVA.sequence();
  seq
    .effect()
    .file(`jb2a.energy_strands.complete.${COLOR}.01`)
    .attachTo(tok.id)
    .scaleToObject(SCALE)
    .layer("belowTokens")
    .fadeIn(FADE_MS, { ease: "easeOutCubic" })
    .fadeOut(FADE_MS, { ease: "easeOutCubic" })
    .persist(true)
    .name(name);
  seq
    .effect()
    .file(`jb2a.energy_strands.overlay.${COLOR}.01`)
    .attachTo(tok.id)
    .scaleToObject(SCALE)
    .fadeIn(FADE_MS, { ease: "easeOutCubic" })
    .fadeOut(FADE_MS, { ease: "easeOutCubic" })
    .persist(true)
    .name(name);
  await seq.play();
}
